mapper.select:
WITH TPN AS ( ), -- Non Repair return T00 AS ( SELECT STOCK.STOFCY_0 AS StockSite, STOCK.ITMREF_0 AS PN, SUM(STOCK.QTYSTU_0) OVER ( PARTITION BY STOCK.ITMREF_0, STOCK.STOFCY_0 ) AS Qty, 'NORM' AS Type FROM TPN INNER JOIN EXPLOIT.STOCK STOCK ON STOCK.ITMREF_0 = TPN.PN WHERE STOCK.STA_0 != 'RE'
-- -- Repair return UNION SELECT STOCK.STOFCY_0 AS StockSite, STOCK.ITMREF_0 + '(RE)' AS PN, SUM(STOCK.QTYSTU_0) OVER ( PARTITION BY STOCK.ITMREF_0, STOCK.STOFCY_0 ) AS Qty, 'RE' AS Type FROM TPN INNER JOIN EXPLOIT.STOCK STOCK ON TPN.PN = STOCK.ITMREF_0 WHERE STOCK.STA_0 = 'RE'
) SELECT * FROM T00 ORDER BY StockSite DESC, Type DESC
